package com.abogacia.microservicio_abogados.correo;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import com.abogacia.microservicio_abogados.entity.*;
class CorreccionesCorreoTest {
 static Estado estado(String nombre){var e=new Estado();e.setNombreEstado(nombre);return e;}
 @Test void normalizaSinEliminarAlias(){assertEquals("usuario+alias@gmail.com",CorreoNormalizado.normalizar(" Usuario+Alias@Gmail.COM "));}
 @Test void cuotaNoSeEludeConMayusculasNiEspacios(){var q=new CuotaCorreo();q.reservar("Usuario@fixture.invalid");q.reservar(" usuario@fixture.invalid ");q.reservar("USUARIO@fixture.invalid");var ex=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->q.reservar("usuario@fixture.invalid"));assertEquals(429,ex.getStatusCode().value());}
 @Test void nuevaDireccionQuedaPendienteSinPerderIdentidad(){var mail=mock(InterfazCorreo.class);var estados=mock(com.abogacia.microservicio_abogados.repository.EstadoRepository.class);when(estados.findByNombreEstado("PENDIENTE")).thenReturn(java.util.Optional.of(estado("PENDIENTE")));var service=new CambiarCorreo(mail,estados,mock(org.springframework.jdbc.core.JdbcTemplate.class),new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder());org.springframework.test.util.ReflectionTestUtils.setField(service,"em",mock(jakarta.persistence.EntityManager.class));var a=new AbogadoRegistrado();a.setMail("old@fixture.invalid");a.setCorreoConfirmado(true);a.setVerificacionDni("APROBADA");a.setEstado(estado("REGISTRADO"));a.setCodigoConfirmacion("anterior");service.cambiar(a," NEW@fixture.invalid ");assertEquals("new@fixture.invalid",a.getMail());assertFalse(a.getCorreoConfirmado());assertEquals("APROBADA",a.getVerificacionDni());assertEquals("PENDIENTE",a.getEstado().getNombreEstado());assertNotEquals("anterior",a.getCodigoConfirmacion());verify(mail).enviarMailConfirmacion(eq("new@fixture.invalid"),anyString());}
 @Test void mismaDireccionNoRevocaNiEnvia(){var mail=mock(InterfazCorreo.class);var jdbc=mock(org.springframework.jdbc.core.JdbcTemplate.class);var service=new CambiarCorreo(mail,mock(com.abogacia.microservicio_abogados.repository.EstadoRepository.class),jdbc,mock(org.springframework.security.crypto.password.PasswordEncoder.class));var a=new AbogadoRegistrado();a.setMail("same@fixture.invalid");a.setCorreoConfirmado(true);a.setCodigoConfirmacion("original");service.cambiar(a," SAME@fixture.invalid ");assertTrue(a.getCorreoConfirmado());assertEquals("original",a.getCodigoConfirmacion());verifyNoInteractions(mail,jdbc);}
 @Test void altaLimitadaSinBloquearConfirmacionNormal()throws Exception{var f=new LimiteCorreo();for(int i=0;i<31;i++){var req=new org.springframework.mock.web.MockHttpServletRequest("POST","/api/abogados");var res=new org.springframework.mock.web.MockHttpServletResponse();f.doFilter(req,res,(q,r)->{});assertEquals(i==30?429:200,res.getStatus());}}
}
